#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> partA, partB;
    int mid_point = n / 2;

    function<void(int, int)> get_sums1 = [&](int i, int total) {
        if (i == mid_point) {
            partA.push_back(total);
        } else {
            get_sums1(i + 1, (total + a[i]) % m);
            get_sums1(i + 1, total);
        }
    };

    function<void(int, int)> get_sums2 = [&](int i, int total) {
        if (i == n) {
            partB.push_back(total);
        } else {
            get_sums2(i + 1, (total + a[i]) % m);
            get_sums2(i + 1, total);
        }
    };

    get_sums1(0, 0);
    get_sums2(mid_point, 0);

    sort(partA.begin(), partA.end());

    int best_sum = 0;
    for (int val : partB) {
        int index = (int)(std::lower_bound(partA.begin(), partA.end(), m - val) - partA.begin());
        if (index > 0) {
            int candidate = partA[index - 1] + val;
            if (candidate > best_sum) {
                best_sum = candidate;
            }
        }
    }

    cout << best_sum << "\n";

    return 0;
}
